CREATE TRIGGER trg_multi
BEFORE INSERT OR UPDATE OR DELETE ON employees
FOR EACH ROW
BEGIN
    IF INSERTING THEN
        DBMS_OUTPUT.PUT_LINE('삽입됨');
    ELSIF UPDATING THEN
        DBMS_OUTPUT.PUT_LINE('수정됨');
    ELSIF DELETING THEN
        DBMS_OUTPUT.PUT_LINE('삭제됨');
    END IF;
END;
